/// The arael version the shim was built with (mirrors arael's Version):
/// the three numbers and the tag after the dash, a static C string,
/// empty for a release.
#[repr(C)]
pub struct CAraelVersion {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
    pub pre: *const c_char,
}

#[repr(C)]
pub struct CCandidateFlops {
    pub amd: f64,
    pub nd: f64,
}

#[repr(C)]
pub struct COptCandidateFlops {
    pub has: bool,
    pub v: CCandidateFlops,
}

/// Mirror of arael's CovPlan: what a covariance assembly decided.
#[repr(C)]
pub struct CCovPlan {
    /// CovOrdering: 0 Auto, 1 Amd, 2 NestedDissection, 3 Natural. Auto
    /// resolves to the candidate it kept, so this never reads 0.
    pub ordering: u32,
    /// Factor flops down each candidate when Auto priced them.
    pub candidate_flops: COptCandidateFlops,
    /// Symbolic analyses built to reach the factor.
    pub symbolics_built: u32,
    /// Whether the block supernodal route ran.
    pub block_route: bool,
}

/// Mirror of arael's SchurPlan: what the sparse backend decided.
/// Field order is C ABI and follows the Rust struct.
#[repr(C)]
pub struct CSchurPlan {
    pub reduced: bool,
    pub eliminated_blocks: u32,
    pub eliminated_params: u32,
    pub kept_params: u32,
    pub fill_ratio: COptDouble,
    pub route_flops: COptRouteFlops,
    pub cg_iterations: COptU32,
    pub flop_ratio: COptDouble,
    /// ReducedOrdering: 0 NaturalBanded, 1 NaturalDense, 2 Amd, 3 Nd.
    pub ordering: COptI32,
    pub kept_bandwidth: u32,
    pub envelope: bool,
    /// Whether the block supernodal Cholesky factorized, rather than
    /// faer's scalar one.
    pub block_supernodal: bool,
}

unsafe fn fill_plan(out: *mut CSchurPlan, p: &arael::simple_lm::SchurPlan) {
    use arael::simple_lm::ReducedOrdering;
    let od = |o: Option<f64>| match o {
        Some(v) => COptDouble { has: true, v },
        None => COptDouble { has: false, v: 0.0 },
    };
    *out = CSchurPlan {
        reduced: p.reduced,
        eliminated_blocks: p.eliminated_blocks as u32,
        eliminated_params: p.eliminated_params as u32,
        kept_params: p.kept_params as u32,
        fill_ratio: od(p.fill_ratio),
        route_flops: match p.route_flops {
            Some((reduced, full)) => COptRouteFlops {
                has: true,
                v: CRouteFlops { reduced, full },
            },
            None => COptRouteFlops {
                has: false,
                v: CRouteFlops { reduced: 0.0, full: 0.0 },
            },
        },
        cg_iterations: match p.cg_iterations {
            Some(n) => COptU32 { has: true, v: n as u32 },
            None => COptU32 { has: false, v: 0 },
        },
        flop_ratio: od(p.flop_ratio),
        ordering: match p.ordering {
            Some(o) => COptI32 {
                has: true,
                v: match o {
                    ReducedOrdering::NaturalBanded => 0,
                    ReducedOrdering::NaturalDense => 1,
                    ReducedOrdering::Amd => 2,
                    ReducedOrdering::NestedDissection => 3,
                },
            },
            None => COptI32 { has: false, v: 0 },
        },
        kept_bandwidth: p.kept_bandwidth as u32,
        envelope: p.envelope,
        block_supernodal: p.block_supernodal,
    };
}

unsafe fn zero_result(out: *mut CLmResult) {
    *out = CLmResult {
        start_cost: 0.0, end_cost: 0.0, iterations: 0,
        accepted_iterations: 0, status: -1, final_lambda: 0.0,
        timing: CLmTiming::default(), has_timing: false,
        detail: std::ptr::null_mut(),
    };
}

unsafe fn fill_result(out: *mut CLmResult, r: &arael::simple_lm::LmResult<f64>) -> i32 {
    let code = status_code(&r.status);
    let (timing, has_timing) = match &r.timing {
        Some(t) => (CLmTiming {
            total: t.total.as_secs_f64(),
            assembly: t.assembly.as_secs_f64(),
            first_assembly: t.first_assembly.as_secs_f64(),
            analysis: t.analysis.as_secs_f64(),
            linear_solve: t.linear_solve.as_secs_f64(),
            first_linear_solve: t.first_linear_solve.as_secs_f64(),
            cost_eval: t.cost_eval.as_secs_f64(),
            first_cost_eval: t.first_cost_eval.as_secs_f64(),
            advance: t.advance.as_secs_f64(),
            first_advance: t.first_advance.as_secs_f64(),
            assembly_count: t.assembly_count as u32,
            analysis_count: t.analysis_count as u32,
            linear_solve_count: t.linear_solve_count as u32,
            cost_eval_count: t.cost_eval_count as u32,
            advance_count: t.advance_count as u32,
            covariance: t.covariance.as_secs_f64(),
        }, true),
        None => (CLmTiming::default(), false),
    };
    *out = CLmResult {
        start_cost: r.start_cost,
        end_cost: r.end_cost,
        iterations: r.iterations as u32,
        accepted_iterations: r.accepted_iterations as u32,
        status: code,
        final_lambda: r.final_lambda,
        timing,
        has_timing,
        detail: std::ptr::null_mut(),
    };
    code
}

fn boxed(r: arael::simple_lm::LmResult<f64>) -> *mut ResultDetail {
    Box::into_raw(Box::new(ResultDetail { result: r, buf: CString::default(), cov_taken: false }))
}

#[no_mangle]
pub extern "C" fn ba_graph_new() -> *mut BaGraphHandle {
    Box::into_raw(Box::new(BaGraphHandle {
        model: Default::default(),
        text: CString::default(),
        failure: CSolveFailure::default(),
    }))
}

#[no_mangle]
pub unsafe extern "C" fn ba_graph_free(h: *mut BaGraphHandle) {
    if !h.is_null() {
        drop(Box::from_raw(h));
    }
}

#[no_mangle]
pub unsafe extern "C" fn ba_graph_last_error(h: *const BaGraphHandle) -> *const c_char {
    (*h).text.as_ptr()
}

/// Text report of the result behind `d` (status, cost, iterations,
/// damping, plus the timing breakdown and the backend's plan when it
/// has them). `pretty` adds colour and box-drawing glyphs. The
/// pointer is valid until the next report call on the same result or
/// ba_graph_result_free.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_report(d: *mut ResultDetail, pretty: bool) -> *const c_char {
    let dd = &mut *d;
    let text = if pretty { dd.result.pretty_report() } else { dd.result.report() };
    dd.buf = CString::new(text.replace('\0', " ")).unwrap_or_default();
    dd.buf.as_ptr()
}

/// The sparse backend's plan for the result behind `d`. Returns false
/// with `out` untouched when the solve carried none (dense and band
/// solves).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_plan(d: *const ResultDetail, out: *mut CSchurPlan) -> bool {
    match &(*d).result.solver {
        Some(arael::simple_lm::SolverReport::Schur(p)) => {
            fill_plan(out, p);
            true
        }
        _ => false,
    }
}

fn c_form(f: &arael::threads::FormTiming) -> CFormTiming {
    CFormTiming {
        calls: f.calls as u32,
        region: f.region.as_secs_f64(),
        task_sum: f.task_sum.as_secs_f64(),
        task_max: f.task_max.as_secs_f64(),
        task_min: f.task_min.as_secs_f64(),
    }
}

fn c_phase(p: &arael::threads::PhaseTiming) -> CPhaseTiming {
    CPhaseTiming { par: c_form(&p.par), seq: c_form(&p.seq) }
}

fn c_footprint(s: &arael::threads::StoreFootprint) -> CStoreFootprint {
    CStoreFootprint {
        self_blocks: s.self_blocks as u64,
        cross_blocks: s.cross_blocks as u64,
        coo_entries: s.coo_entries as u64,
        bytes: s.bytes as u64,
    }
}

fn c_choice(c: &arael::threads::PhaseChoice) -> CPhaseChoice {
    CPhaseChoice { threaded: c.threaded, calls: c.calls as u32 }
}

/// What the solve's threads did, for the result behind `d`.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_threads(d: *const ResultDetail, out: *mut CThreadReport) {
    let t = &(*d).result.threads;
    let sweeps = match &t.sweeps {
        Some(s) => {
            let g = &s.timing;
            COptSweepReport {
                has: true,
                v: CSweepReport {
                    threads: s.threads as u32,
                    assembly: c_choice(&s.assembly),
                    cost: c_choice(&s.cost),
                    timing: CParTiming {
                        on: g.on,
                        bind: g.bind.as_secs_f64(),
                        assembly_update: g.assembly_update.as_secs_f64(),
                        assembly_zero: g.assembly_zero.as_secs_f64(),
                        assembly: c_phase(&g.assembly),
                        gather_grad: g.gather_grad.as_secs_f64(),
                        assembly_zero_vals: g.assembly_zero_vals.as_secs_f64(),
                        scatter: g.scatter.as_secs_f64(),
                        cost_update: g.cost_update.as_secs_f64(),
                        cost: c_phase(&g.cost),
                    },
                    whole: c_footprint(&s.whole),
                    held: s.held.len() as u32,
                },
            }
        }
        None => COptSweepReport::default(),
    };
    *out = CThreadReport {
        sweeps_asked: t.sweeps_asked as u32,
        linear: t.linear as u32,
        fell_back: t.fell_back(),
        sweeps,
    };
}

/// What each split store of the result behind `d` holds
/// (SweepReport::held). Copies up to `cap` records into `out` and
/// returns the total count -- call with cap 0 to size the buffer.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_threads_held(d: *const ResultDetail, out: *mut CStoreFootprint, cap: u64) -> u64 {
    let held: &[arael::threads::StoreFootprint] = match &(*d).result.threads.sweeps {
        Some(s) => &s.held,
        None => &[],
    };
    for (i, s) in held.iter().take(cap as usize).enumerate() {
        *out.add(i) = c_footprint(s);
    }
    held.len() as u64
}

/// The covariance the config asked for (CLmConfig::covariance),
/// assembled at the solution by the solve behind `d`. Moves it out of
/// the result: returns 0 and the owned handle in `out` (release with
/// ba_graph_cov_free), 1 with `out` null when the config did not
/// ask, 2 when an earlier call already took it, -1 when the assembly
/// failed (text via ba_graph_result_error).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_covariance(d: *mut ResultDetail, out: *mut *mut BaGraphCov) -> i32 {
    *out = std::ptr::null_mut();
    let dd = &mut *d;
    if dd.cov_taken {
        return 2;
    }
    match std::mem::replace(&mut dd.result.covariance, Err(CovError::NotRequested)) {
        Ok(c) => {
            dd.cov_taken = true;
            *out = Box::into_raw(Box::new(BaGraphCov { cov: c, text: CString::default() }));
            0
        }
        Err(CovError::NotRequested) => 1,
        Err(e) => {
            dd.result.covariance = Err(e);
            dd.buf = CString::new(format!("{}", e).replace('\0', " ")).unwrap_or_default();
            -1
        }
    }
}

/// The text of the last failure reported by a call on the result
/// behind `d` (ba_graph_result_covariance). Valid until the next
/// call on the same result or ba_graph_result_free.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_error(d: *const ResultDetail) -> *const c_char {
    (*d).buf.as_ptr()
}

/// Per-attempt timeline of the result behind `d` (LmTiming::steps;
/// populated when the solve ran with gather_timing, empty
/// otherwise). Copies up to `cap` records into `out` and returns the
/// total count -- call with cap 0 to size the buffer.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_steps(d: *const ResultDetail, out: *mut CLmStep, cap: u64) -> u64 {
    let steps: &[arael::simple_lm::LmStep] = match &(*d).result.timing {
        Some(t) => &t.steps,
        None => &[],
    };
    for (i, s) in steps.iter().take(cap as usize).enumerate() {
        *out.add(i) = CLmStep {
            iter: s.iter as u32,
            inner: s.inner as u32,
            accepted: s.accepted,
            factorization_failed: s.factorization_failed,
            lambda: s.lambda,
            cost: s.cost,
            new_cost: s.new_cost,
            step_norm: s.step_norm,
            grad_max: s.grad_max,
            time: s.time.as_secs_f64(),
            assembly: s.assembly.as_secs_f64(),
            analysis: s.analysis.as_secs_f64(),
            linear_solve: s.linear_solve.as_secs_f64(),
            cost_eval: s.cost_eval.as_secs_f64(),
            advance: s.advance.as_secs_f64(),
        };
    }
    steps.len() as u64
}

/// Release the Rust result behind a CLmResult. Null is fine.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_result_free(d: *mut ResultDetail) {
    if !d.is_null() {
        drop(Box::from_raw(d));
    }
}

/// Drop arael log messages above `level` (0 Off, 1 Error, 2 Warn,
/// 3 Info; Info -- everything -- is the default). Process-wide: all
/// models and roots share it.
#[no_mangle]
pub extern "C" fn ba_graph_set_log_level(level: u32) {
    arael::log::set_level(match level {
        0 => arael::log::Level::Off,
        1 => arael::log::Level::Error,
        2 => arael::log::Level::Warn,
        _ => arael::log::Level::Info,
    });
}

/// Stop and join arael's sweep worker threads; the next threaded solve
/// spawns them again. Process-wide. Without the `threads` feature no
/// worker is ever spawned and it returns at once.
#[no_mangle]
pub extern "C" fn ba_graph_pool_shutdown() {
    arael::pool::shutdown();
}

/// The arael version the shim was built with; `pre` points at a static
/// C string.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_arael_version(out: *mut CAraelVersion) {
    static PRE: std::sync::OnceLock<CString> = std::sync::OnceLock::new();
    *out = CAraelVersion {
        major: arael::VERSION.major,
        minor: arael::VERSION.minor,
        patch: arael::VERSION.patch,
        pre: PRE.get_or_init(|| CString::new(arael::VERSION.pre).unwrap()).as_ptr(),
    };
}

/// Empty string when the model is clean, the Diagnostic text otherwise.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_validate(h: *mut BaGraphHandle) -> *const c_char {
    let hh = &mut *h;
    let text = match catch_unwind(AssertUnwindSafe(|| {
        let d = hh.model.validate();
        if d.is_clean() { String::new() } else { d.to_string() }
    })) {
        Ok(t) => t,
        Err(p) => panic_text(p),
    };
    set_text(hh, &text);
    hh.text.as_ptr()
}

/// Returns the status code (>= 0: LmStatus; -1: solve failure; -2:
/// panic). Failure text via ba_graph_last_error. On success (and on
/// a failure that got past its first assembly, where `out` carries
/// the partial result) `out.detail` owns the full Rust result --
/// release it with ba_graph_result_free.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_solve_dense(
    h: *mut BaGraphHandle,
    cfg: *const CLmConfig,
    out: *mut CLmResult,
) -> i32 {
    let hh = &mut *h;
    let c = (*cfg).to_config();
    zero_result(out);
    match catch_unwind(AssertUnwindSafe(|| hh.model.solve_dense(&c))) {
        Ok(Ok(r)) => {
            let code = fill_result(out, &r);
            (*out).detail = boxed(r);
            set_text(hh, "");
            hh.failure = CSolveFailure::default();
            code
        }
        Ok(Err(f)) => {
            set_text(hh, &f.to_string());
            hh.failure = failure_of(&f.kind);
            if let Some(p) = f.partial {
                fill_result(out, &p);
                (*out).status = -1;
                (*out).detail = boxed(*p);
            }
            -1
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            hh.failure = CSolveFailure::default();
            (*out).status = -2;
            -2
        }
    }
}

/// As ba_graph_solve_dense, with the sparse backend. `opts` selects
/// its route (ordering, Schur policy, envelope); null means the
/// defaults (ba_graph_sparse_options shows them).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_solve_sparse(
    h: *mut BaGraphHandle,
    cfg: *const CLmConfig,
    opts: *const CSparseOptions,
    out: *mut CLmResult,
) -> i32 {
    let hh = &mut *h;
    let c = (*cfg).to_config();
    zero_result(out);
    match catch_unwind(AssertUnwindSafe(|| {
        if opts.is_null() {
            hh.model.solve_sparse(&c)
        } else {
            let mut s = SparseFaer::<f64>::from_options(&(*opts).to_options());
            hh.model.solve_with(&mut s, &c)
        }
    })) {
        Ok(Ok(r)) => {
            let code = fill_result(out, &r);
            (*out).detail = boxed(r);
            set_text(hh, "");
            hh.failure = CSolveFailure::default();
            code
        }
        Ok(Err(f)) => {
            set_text(hh, &f.to_string());
            hh.failure = failure_of(&f.kind);
            if let Some(p) = f.partial {
                fill_result(out, &p);
                (*out).status = -1;
                (*out).detail = boxed(*p);
            }
            -1
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            hh.failure = CSolveFailure::default();
            (*out).status = -2;
            -2
        }
    }
}

/// A warm-reuse session over the sparse backend (Rust's LmSession):
/// keeps the analysis -- pattern, ordering, symbolic factorization,
/// Schur plan -- across solves, so only the first pays for it. Warm
/// solves are bit-identical to cold ones. Call
/// ba_graph_session_invalidate after any structural change: a
/// changed parameter or block count without it fails the solve, and a
/// change that keeps every count solves warm through stale analysis
/// (undefined).
pub struct BaGraphSession {
    // Err carries a construction panic (a bad options tag), reported
    // by the first solve.
    session: Result<LmSession<f64, SparseFaer<f64>>, String>,
}

/// New session; `opts` as in ba_graph_solve_sparse (null =
/// defaults). Never fails: a bad options tag is reported by the
/// first solve (status -2 with the tag in the text).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_session_new(
    opts: *const CSparseOptions,
) -> *mut BaGraphSession {
    let session = catch_unwind(AssertUnwindSafe(|| {
        if opts.is_null() {
            LmSession::new(SparseFaer::<f64>::new())
        } else {
            LmSession::new(SparseFaer::<f64>::from_options(&(*opts).to_options()))
        }
    })).map_err(panic_text);
    Box::into_raw(Box::new(BaGraphSession { session }))
}

#[no_mangle]
pub unsafe extern "C" fn ba_graph_session_free(s: *mut BaGraphSession) {
    if !s.is_null() {
        drop(Box::from_raw(s));
    }
}

/// Drop the learned structure; the next solve runs cold.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_session_invalidate(s: *mut BaGraphSession) {
    if let Ok(sess) = &mut (*s).session {
        sess.invalidate();
    }
}

/// As ba_graph_solve_sparse, through the session's cached analysis.
/// Error text lands on the model handle (ba_graph_last_error).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_session_solve(
    s: *mut BaGraphSession,
    h: *mut BaGraphHandle,
    cfg: *const CLmConfig,
    out: *mut CLmResult,
) -> i32 {
    let ss = &mut *s;
    let hh = &mut *h;
    let c = (*cfg).to_config();
    zero_result(out);
    let session = match &mut ss.session {
        Ok(sess) => sess,
        Err(msg) => {
            let msg = msg.clone();
            set_text(hh, &msg);
            (*out).status = -2;
            return -2;
        }
    };
    match catch_unwind(AssertUnwindSafe(|| session.solve(&mut hh.model, &c))) {
        Ok(Ok(r)) => {
            let code = fill_result(out, &r);
            (*out).detail = boxed(r);
            set_text(hh, "");
            hh.failure = CSolveFailure::default();
            code
        }
        Ok(Err(f)) => {
            set_text(hh, &f.to_string());
            hh.failure = failure_of(&f.kind);
            if let Some(p) = f.partial {
                fill_result(out, &p);
                (*out).status = -1;
                (*out).detail = boxed(*p);
            }
            -1
        }
        Err(p) => {
            // A panic mid-solve may leave the session's cached
            // analysis half-built; drop it so the next solve is cold.
            session.invalidate();
            let msg = panic_text(p);
            set_text(hh, &msg);
            hh.failure = CSolveFailure::default();
            (*out).status = -2;
            -2
        }
    }
}

/// Band Cholesky solve; `kd` is the Hessian half-bandwidth in scalar
/// parameters. Returns the status code (>= 0: LmStatus; -1: solve
/// failure; -2: panic). Failure text via ba_graph_last_error;
/// `out.detail` as in the other solves.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_solve_band(
    h: *mut BaGraphHandle,
    kd: u32,
    cfg: *const CLmConfig,
    out: *mut CLmResult,
) -> i32 {
    let hh = &mut *h;
    let c = (*cfg).to_config();
    zero_result(out);
    match catch_unwind(AssertUnwindSafe(|| {
        hh.model.solve_with(&mut arael::simple_lm::Band::new(kd as usize), &c)
    })) {
        Ok(Ok(r)) => {
            let code = fill_result(out, &r);
            (*out).detail = boxed(r);
            set_text(hh, "");
            hh.failure = CSolveFailure::default();
            code
        }
        Ok(Err(f)) => {
            set_text(hh, &f.to_string());
            hh.failure = failure_of(&f.kind);
            if let Some(p) = f.partial {
                fill_result(out, &p);
                (*out).status = -1;
                (*out).detail = boxed(*p);
            }
            -1
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            hh.failure = CSolveFailure::default();
            (*out).status = -2;
            -2
        }
    }
}

/// Total cost at the current parameter values (evaluated at the
/// model's precision, returned as f64). NaN on a caught panic, with
/// the text via ba_graph_last_error (a healthy cost can also be NaN
/// -- non-finite parameters -- so check last_error to distinguish).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_cost(h: *mut BaGraphHandle) -> f64 {
    let hh = &mut *h;
    match catch_unwind(AssertUnwindSafe(|| {
        let mut params = Vec::new();
        hh.model.serialize(&mut params);
        hh.model.calc_cost(&params)
    })) {
        Ok(c) => {
            set_text(hh, "");
            c
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            f64::NAN
        }
    }
}

/// An assembled covariance, owned by the caller (release with
/// ba_graph_cov_free). Independent of later assemblies; entity
/// arguments to its queries must come from the live model.
pub struct BaGraphCov {
    cov: CovAssembly,
    text: CString,
}

fn cov_text(c: &mut BaGraphCov, msg: &str) {
    c.text = CString::new(msg.replace('\0', " ")).unwrap_or_default();
}

/// Error text of the last failed query on this assembly.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_cov_error(c: *const BaGraphCov) -> *const c_char {
    (&*c).text.as_ptr()
}

/// What the assembly decided. Always succeeds -- every assembly has a plan.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_cov_plan(c: *const BaGraphCov, out: *mut CCovPlan) {
    let p = (&*c).cov.plan();
    *out = CCovPlan {
        ordering: match p.ordering {
            arael::covariance::CovOrdering::Auto => 0,
            arael::covariance::CovOrdering::Amd => 1,
            arael::covariance::CovOrdering::NestedDissection => 2,
            arael::covariance::CovOrdering::Natural => 3,
        },
        candidate_flops: match p.candidate_flops {
            Some((amd, nd)) => COptCandidateFlops {
                has: true,
                v: CCandidateFlops { amd, nd },
            },
            None => COptCandidateFlops {
                has: false,
                v: CCandidateFlops { amd: 0.0, nd: 0.0 },
            },
        },
        symbolics_built: p.symbolics_built as u32,
        block_route: (&*c).cov.took_block_route(),
    };
}

/// Release an assembly. Null is fine.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_cov_free(c: *mut BaGraphCov) {
    if !c.is_null() {
        drop(Box::from_raw(c));
    }
}

/// mode: 0 = PerQuery, 1 = AllMarginals, 2 = TriDiagonal. On 0 `out`
/// holds the owned assembly; -1 (error, text via
/// ba_graph_last_error), -2 (panic).
#[no_mangle]
pub unsafe extern "C" fn ba_graph_assemble_covariance(h: *mut BaGraphHandle, mode: u32, out: *mut *mut BaGraphCov) -> i32 {
    ba_graph_assemble_covariance_with(h, mode, 0, 0, out)
}

/// ba_graph_assemble_covariance with the assembly spelled out.
/// ordering: 0 = Auto, 1 = Amd, 2 = NestedDissection, 3 = Natural.
/// block_supernodal: 0 = Auto, 1 = Always, 2 = Never.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_assemble_covariance_with(
    h: *mut BaGraphHandle, mode: u32, ordering: u32, block_supernodal: u32,
    out: *mut *mut BaGraphCov,
) -> i32 {
    let mut ctx = arael::threads::Context::new();
    ba_graph_cov_build(&mut *h, mode, ordering, block_supernodal, &mut ctx, out)
}

/// ba_graph_assemble_covariance reusing what the session's solves
/// built. Error text lands on the model handle.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_session_assemble_covariance(
    s: *mut BaGraphSession, h: *mut BaGraphHandle, mode: u32, out: *mut *mut BaGraphCov,
) -> i32 {
    ba_graph_session_assemble_covariance_with(s, h, mode, 0, 0, out)
}

/// ba_graph_session_assemble_covariance with the assembly spelled out.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_session_assemble_covariance_with(
    s: *mut BaGraphSession, h: *mut BaGraphHandle, mode: u32, ordering: u32, block_supernodal: u32,
    out: *mut *mut BaGraphCov,
) -> i32 {
    let hh = &mut *h;
    *out = std::ptr::null_mut();
    match &mut (*s).session {
        Ok(sess) => ba_graph_cov_build(hh, mode, ordering, block_supernodal, sess.context_mut(), out),
        Err(msg) => {
            let msg = msg.clone();
            set_text(hh, &msg);
            -2
        }
    }
}

unsafe fn ba_graph_cov_build(
    hh: &mut BaGraphHandle, mode: u32, ordering: u32, block_supernodal: u32,
    ctx: &mut arael::threads::Context, out: *mut *mut BaGraphCov,
) -> i32 {
    *out = std::ptr::null_mut();
    let m = cov_mode_of(mode);
    let opts = cov_options_of(ordering, block_supernodal);
    match catch_unwind(AssertUnwindSafe(|| hh.model.assemble_covariance_with(m, &opts, ctx))) {
        Ok(Ok(c)) => {
            *out = Box::into_raw(Box::new(BaGraphCov {
                cov: c,
                text: CString::default(),
            }));
            set_text(hh, "");
            0
        }
        Ok(Err(e)) => {
            set_text(hh, &format!("{}", e));
            -1
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            -2
        }
    }
}

/// Row-major dim x dim marginal covariance (f64) of one `BaCam`; returns
/// dim, or -1 (error) / -2 (panic) / -3 (buffer too small), text via ba_graph_cov_error.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_ba_cam_marginal_cov(
    c: *mut BaGraphCov,
    p: *const BaCam,
    out: *mut f64,
    cap: u32,
) -> i32 {
    let cc = &mut *c;
    match catch_unwind(AssertUnwindSafe(|| cc.cov.marginal_cov(&*p))) {
        Ok(Ok(m)) => {
            let dim = m.nrows();
            if (dim * dim) as u32 > cap {
                cov_text(cc, "marginal_cov: buffer too small");
                return -3;
            }
            for r in 0..dim {
                for c in 0..dim {
                    *out.add(r * dim + c) = m[(r, c)];
                }
            }
            dim as i32
        }
        Ok(Err(e)) => {
            cov_text(cc, &format!("{}", e));
            -1
        }
        Err(p2) => {
            let msg = panic_text(p2);
            cov_text(cc, &msg);
            -2
        }
    }
}
