pub unsafe extern "C" fn ba_graph_cams_len(p: *const BaGraphHandle) -> u32 {
    (*p).model.cams.len() as u32
}
#[no_mangle]
pub unsafe extern "C" fn ba_graph_cams_reserve(p: *mut BaGraphHandle, additional: u32) {
    (*p).model.cams.reserve(additional as usize);
}
