pub unsafe extern "C" fn ba_graph_cams_at(p: *mut BaGraphHandle, i: u32) -> *mut BaCam {
    let m = &mut (*p).model.cams;
    &mut m[i as usize] as *mut BaCam
}
/// Drops the last element; false when already empty.
#[no_mangle]
pub unsafe extern "C" fn ba_graph_cams_pop(p: *mut BaGraphHandle) -> bool {
    (*p).model.cams.pop().is_some()
}
